"use client";

import Link from "next/link";
import { useAuth } from "@/lib/auth-context";
import { api } from "@/lib/api";
import { useIdempotency } from "@/lib/idempotency";
import { Button } from "@/components/ui/button";
import CartButton from "./cartButton";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Store } from "lucide-react";

/**
 * The one header.
 *
 * There used to be a second, authenticated Navbar alongside this one, split because that one
 * hard-linked to routes a guest cannot reach. There is now a single (shop) route group for the
 * storefront and the account pages alike, so there is one header and it has to work for both: the
 * account menu offers Profile, Settings and Logout when signed in, and Log in / Sign up when not.
 *
 * Its links have to stay guest-safe for the same reason the single shell does — this header sits
 * above the marketplace, which is the one page that must render for anyone.
 */
export default function StorefrontHeader() {
  const { user, refreshUser } = useAuth();
  const idem = useIdempotency();

  async function handleLogout() {
    try {
      await idem.run((idempotencyKey) =>
        api("/logout", { method: "POST", idempotencyKey })
      );
    } catch {
      // logout clears cookies regardless
    }
    await refreshUser();
    window.location.href = "/login";
  }

  return (
    <header className="sticky top-0 z-30 border-b border-border bg-background">
      <div className="mx-auto flex h-14 max-w-[1400px] items-center gap-4 px-4">
        <Link href="/marketplace" className="flex items-center gap-2 font-semibold">
          <Store className="size-4" />
          <span>sampledomain</span>
        </Link>

        <div className="flex flex-1 items-center">
          <Link
            href="/marketplace"
            className="rounded-lg px-2 py-1 text-sm text-muted-foreground hover:bg-muted hover:text-foreground"
          >
            Marketplace
          </Link>
        </div>

        <CartButton />

        {user ? (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="ghost" size="icon" className="rounded-full">
                <Avatar size="lg">
                  <AvatarFallback>
                    {user.name?.charAt(0).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <span className="sr-only">Open account menu</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="w-52">
              <DropdownMenuLabel>{user.name}</DropdownMenuLabel>
              <DropdownMenuSeparator />
              <DropdownMenuItem asChild>
                <Link href="/profile">Profile</Link>
              </DropdownMenuItem>
              <DropdownMenuItem asChild>
                <Link href="/settings">Settings</Link>
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem variant="destructive" onSelect={handleLogout}>
                Logout
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        ) : (
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" asChild>
              <Link href="/login">Log in</Link>
            </Button>
            <Button size="sm" asChild>
              <Link href="/register">Sign up</Link>
            </Button>
          </div>
        )}
      </div>
    </header>
  );
}